```go
package dominoes

// Domino represents a single domino stone with two halves.
type Domino [2]int

// MakeChain returns a closed chain that uses every domino in input exactly once,
// or reports that no such chain exists.
func MakeChain(input []Domino) ([]Domino, bool) {
	chain := make([]Domino, 0, len(input))
	if solve(input, 0, chain, -1) {
		return chain, true
	}
	return nil, false
}

// solve tries to place the remaining dominoes after the current chain,
// continuing from the face `end`.
func solve(remaining []Domino, end int, chain []Domino, start int) bool {
	if len(remaining) == 0 {
		return start == end
	}
	for i, d := range remaining {
		rest := append(append([]Domino{}, remaining[:i]...), remaining[i+1:]...)
		if d[0] == end {
			if solve(rest, d[1], append(chain, d), start) {
				return true
			}
		}
		if d[1] == end && d[0] != d[1] {
			if solve(rest, d[0], append(chain, [2]int{d[1], d[0]}), start) {
				return true
			}
		}
	}
	return false
}
```

