type Domino [2]int

// MakeChain finds a closed chain that uses every domino in input exactly once.
// A chain is closed when adjacent halves match and the two exposed halves
// (first and last) match each other. It returns the chain and true if one
// exists, or nil and false otherwise.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}
	chain := make([]Domino, 0, len(input))
	for i, d := range input {
		rest := append(append([]Domino(nil), input[:i]...), input[i+1:]...)
		if solve(rest, d[1], append(chain, d), d[0]) {
			return chain, true
		}
		if d[1] != d[0] {
			if solve(rest, d[0], append(chain, [2]int{d[1], d[0]}), d[1]) {
				return chain, true
			}
		}
	}
	return nil, false
}

// solve extends the chain (which currently ends with the face end) by placing
// one of the remaining dominoes, and recurses until every domino is used.
// The chain is only accepted if its final face equals the face start.
func solve(remaining []Domino, end int, chain []Domino, start int) bool {
	if len(remaining) == 0 {
		return start == end
